BEGIN TRANSACTION;
CREATE TABLE cameras (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	source VARCHAR(255) NOT NULL, 
	source_type VARCHAR(20) NOT NULL, 
	resolution VARCHAR(20), 
	fps INTEGER, 
	confidence_threshold FLOAT, 
	face_threshold FLOAT, 
	line_orientation VARCHAR(20), 
	line_position FLOAT, 
	enabled BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE TABLE events (
	id INTEGER NOT NULL, 
	camera_id INTEGER, 
	person_id INTEGER, 
	entity_type VARCHAR(50) NOT NULL, 
	entity_name VARCHAR(100) NOT NULL, 
	recognition_status VARCHAR(30), 
	event_type VARCHAR(50), 
	direction VARCHAR(30), 
	confidence FLOAT, 
	snapshot_path VARCHAR(255), 
	timestamp DATETIME NOT NULL, 
	metadata_json TEXT, severity VARCHAR(20) DEFAULT 'INFO', zone_name VARCHAR(100), is_acknowledged BOOLEAN DEFAULT 0, acknowledged_at DATETIME, acknowledged_by VARCHAR(100), 
	PRIMARY KEY (id), 
	FOREIGN KEY(camera_id) REFERENCES cameras (id) ON DELETE SET NULL, 
	FOREIGN KEY(person_id) REFERENCES persons (id) ON DELETE SET NULL
);
CREATE TABLE face_embeddings (
	id INTEGER NOT NULL, 
	person_id INTEGER NOT NULL, 
	embedding_json TEXT NOT NULL, 
	sample_image_path VARCHAR(255), 
	quality_score FLOAT, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(person_id) REFERENCES persons (id) ON DELETE CASCADE
);
CREATE TABLE notifications (
	id INTEGER NOT NULL, 
	event_id INTEGER, 
	title VARCHAR(150) NOT NULL, 
	message TEXT NOT NULL, 
	severity VARCHAR(20) NOT NULL, 
	read_status BOOLEAN NOT NULL, 
	created_at DATETIME NOT NULL, category VARCHAR(30) DEFAULT 'ALL', is_acknowledged BOOLEAN DEFAULT 0, 
	PRIMARY KEY (id), 
	FOREIGN KEY(event_id) REFERENCES events (id) ON DELETE CASCADE
);
CREATE TABLE persons (
	id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	person_code VARCHAR(50), 
	email VARCHAR(120), 
	phone VARCHAR(30), 
	status VARCHAR(20) NOT NULL, 
	notes TEXT, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE restricted_zones (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    camera_id INTEGER NOT NULL REFERENCES cameras(id) ON DELETE CASCADE,
    name VARCHAR(100) NOT NULL,
    boundary_type VARCHAR(20) NOT NULL DEFAULT 'rectangle',
    coordinates_json TEXT NOT NULL DEFAULT '{}',
    allowed_hours_start VARCHAR(10) NOT NULL DEFAULT '08:00',
    allowed_hours_end VARCHAR(10) NOT NULL DEFAULT '20:00',
    authorized_person_ids_json TEXT NOT NULL DEFAULT '[]',
    alert_level VARCHAR(20) NOT NULL DEFAULT 'HIGH',
    enabled BOOLEAN NOT NULL DEFAULT 1,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE system_settings (
	id INTEGER NOT NULL, 
	setting_name VARCHAR(100) NOT NULL, 
	setting_value TEXT NOT NULL, 
	description VARCHAR(255), 
	updated_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE users (
	id INTEGER NOT NULL, 
	username VARCHAR(64) NOT NULL, 
	password_hash VARCHAR(256) NOT NULL, 
	role VARCHAR(20) NOT NULL, 
	full_name VARCHAR(100), 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);
CREATE UNIQUE INDEX ix_users_username ON users (username);
CREATE UNIQUE INDEX ix_persons_person_code ON persons (person_code);
CREATE INDEX ix_persons_name ON persons (name);
CREATE UNIQUE INDEX ix_system_settings_setting_name ON system_settings (setting_name);
CREATE INDEX ix_face_embeddings_person_id ON face_embeddings (person_id);
CREATE INDEX ix_events_event_type ON events (event_type);
CREATE INDEX ix_events_entity_type ON events (entity_type);
CREATE INDEX ix_events_recognition_status ON events (recognition_status);
CREATE INDEX ix_events_person_id ON events (person_id);
CREATE INDEX ix_events_camera_id ON events (camera_id);
CREATE INDEX ix_events_timestamp ON events (timestamp);
CREATE INDEX ix_notifications_created_at ON notifications (created_at);
CREATE INDEX ix_notifications_read_status ON notifications (read_status);
CREATE INDEX ix_notifications_event_id ON notifications (event_id);
DELETE FROM "sqlite_sequence";
COMMIT;
